def apply_rules(grid):
    """
    Applies the bacterial spread rules simultaneously to the grid.
    (Function definition remains the same as before)
    """
    current_grid = np.copy(grid)
    next_grid = np.copy(grid)

    # --- Stage 1: Apply Growth (Rule 1) changes ---
    for r in range(N - 1):
        for c in range(N - 1):
            block = current_grid[r:r+2, c:c+2]
            count = np.sum(block)

            if count == 3:
                sterile_indices = np.argwhere(block == 0)
                if len(sterile_indices) == 1:
                    r_idx, c_idx = sterile_indices[0]
                    next_grid[r + r_idx, c + c_idx] = 1

    # --- Stage 2: Determine Flips (Rule 2) based on the original state ---
    flip_mask = np.zeros((N, N), dtype=bool)
    for r in range(N - 1):
        for c in range(N - 1):
            block = current_grid[r:r+2, c:c+2]
            count = np.sum(block)

            if count == 2:
                for dr in range(2):
                    for dc in range(2):
                        flip_mask[r + dr, c + dc] = True

    # --- Stage 3: Apply Mutations (Rule 2) to the growth state ---
    final_grid = np.copy(next_grid)
    for r in range(N):
        for c in range(N):
            if flip_mask[r, c]:
                final_grid[r, c] = 1 - final_grid[r, c]

    return final_grid

def simulate_spread(initial_config, k):
    """Runs the simulation until full infection, stable state, or cycle detection."""
    grid = np.copy(initial_config)

    if np.sum(grid) != k:
        return "ERROR: Initial count mismatch"

    history = {}

    for cycle in range(MAX_CYCLES):
        if np.all(grid == 1):
            return f"Full Infection (Cycles: {cycle})"

        grid_tuple = tuple(map(tuple, grid))
        if grid_tuple in history:
            return f"Cycle detected (Cycle length: {cycle - history[grid_tuple]})"

        history[grid_tuple] = cycle

        grid = apply_rules(grid)

    return f"Stable or Stuck (Cycles: {MAX_CYCLES})"

def generate_configs(N, k, max_configs):
    """Generates up to max_configs k-infected configurations (samples)."""
    all_coords = [(r, c) for r in range(N) for c in range(N)]
    configs = []
    count = 0

